    ($SATQ$88a0c425$SATQ$, $SATQ$87a33c1a-0dd6-4c06-953e-5ebde0abb83e$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Advanced Math$SATQ$, $SATQ$P$SATQ$, $SATQ$P.B.$SATQ$, $SATQ$Nonlinear equations in one variable and systems of equations in two variables $SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="minus 2 x squared plus 20 x plus c equals 0"><mrow>
	<mrow>
		<mrow>
			<mo>-</mo>
			<mn>2</mn>
			<msup>
				<mi>x</mi>
				<mn>2</mn>
			</msup>
		</mrow>
		<mo>+</mo>
		<mrow>
			<mn>20</mn>
			<mi>x</mi>
		</mrow>
