82822 \nL 54.828549 152.329241 \nL 61.312725 147.063535 \nL 67.796901 142.085702 \nL 74.281076 137.395745 \nL 80.765252 132.993662 \nL 86.844167 129.128158 \nL 92.923082 125.515669 \nL 99.001997 122.156195 \nL 105.080912 119.049735 \nL 111.159827 116.196291 \nL 117.238742 113.595861 \nL 123.317657 111.248446 \nL 129.396572 109.154045 \nL 135.070226 107.427547 \nL 140.74388 105.921453 \nL 146.417534 104.635763 \nL 152.091188 103.570477 \nL 157.764842 102.725595 \nL 163.438496 102.101117 \nL 169.11215 101.697043 \nL 174.785804 101.513373 \nL 180.459458 101.550107 \nL 186.133112 101.807245 \nL 191.806766 102.284787 \nL 197.48042 102.982733 \nL 203.154074 103.901083 \nL 208.827727 105.039837 \nL 214.501381 106.398995 \nL 220.175035 107.978557 \nL 225.848689 109.778523 \nL 231.522343 111.798893 \nL 237.601258 114.208156 \nL 243.680173 116.870434 \nL 244.085434 117.056916 \nL 244.085434 117.056916 \n\" style=\"fill:none;stroke:#000000;stroke-linecap:square;stroke-width:2.3;\"></path>\n   </g>\n  </g>\n </g>\n <defs>\n  <clipPath id=\"p8b6339c06d\">\n   <rect height=\"260.82\" width=\"262.488358\" x=\"9.200821\" y=\"7.2\"></rect>\n  </clipPath>\n </defs>\n</svg>\n<div role=\"region\" aria-label=\"Long description for graph of a parabola\" class=\"sr-only\"><ul><li>The parabola opens downward.</li>\n<li>The vertex is at point (4 comma 9).</li>\n<li>The parabola passes through the following points:<br>\n<ul>\n<li>(0 comma 5)</li>\n<li>(2 comma 8)</li>\n<li>(4 comma 9)</li>\n<li>(6 comma 8)</li>\n</ul>\n</li>\n</ul></div></figure></p>\n<p style=\"text-align: left;\">The graph models the number of active projects a company was working on <math alttext=\"x\"><mi>x</mi>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn>\n</math>, where <math alttext=\"0 less than or equals x less than or equals 6\"><mn>0</mn><mo>&#8804;</mo><mi>x</mi><mo>&#8804;</mo><mn>6</mn></math>. According to the model, what is the predicted number of active projects the company was working on at the end of November <math alttext=\"2012\"><mn>2012</mn>\n</math>?</p>","answerOptions":[{"id":"9decb121-47d5-4d6e-9d18-d34abf44af02","content":"<p><math alttext=\"0\"><mn>0</mn>\n</math></p>"},{"id":"f7707352-7a41-41a7-a120-8e8d6dc57e04","content":"<p><math alttext=\"5\"><mn>5</mn>\n</math></p>"},{"id":"b4573a81-e704-45ed-840f-8badfdd6e5e0","content":"<p><math alttext=\"8\"><mn>8</mn>\n</math></p>"},{"id":"f227815d-2851-4ac8-a99b-8768c426f2be","content":"<p><math alttext=\"9\"><mn>9</mn>\n</math></p>"}],"keys":["f7707352-7a41-41a7-a120-8e8d6dc57e04"],"correct_answer":["B"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. It's given that the graph models the number of active projects a company was working on <math alttext=\"x\"><mi>x</mi>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>. Therefore, the value of <math alttext=\"x\"><mi>x</mi>\n</math> that corresponds to the end of November <math alttext=\"2012\"><mn>2012</mn></math> is <math alttext=\"0\"><mn>0</mn>\n</math>. The point at which <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math> is the <em>y</em>-intercept of the graph. It follows that the <em>y</em>-intercept of the graph shown is the point <math alttext=\"left parenthesis 0 comma 5 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>. Therefore, according to the model, the predicted number of active projects the company was working on at the end of November <math alttext=\"2012\"><mn>2012</mn></math> is <math alttext=\"5\"><mn>5</mn>\n</math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the value of <math alttext=\"x\"><mi>x</mi>\n</math> that corresponds to the end of November <math alttext=\"2012\"><mn>2012</mn></math>, not the predicted number of active projects the company was working on at the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>\n<p style=\"text-align: left;\">Choice C is incorrect. This is the predicted number of active projects the company was working on <math alttext=\"2\"><mn>2</mn>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. This is the predicted number of active projects the company was working on <math alttext=\"4\"><mn>4</mn>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"image_count":0,"raw_list":{"updateDate":1730147357398,"pPcc":"SAT#P","questionId":"95d1c344","skill_cd":"P.C.","score_band_range_cd":4,"skill_desc":"Nonlinear functions","createDate":1730147357398,"program":"SAT","primary_class_cd_desc":"Advanced Math","ibn":"","external_id":"d900a2e7-10e1-484e-a11a-0c2fe3bbb04f","primary_class_cd":"P","uId":"3050c384-7181-4285-a046-f98272c33cb0","difficulty":"M"},"raw_detail":{"answerOptions":[{"content":"<p><math alttext=\"0\"><mn>0</mn>\n</math></p>","id":"9decb121-47d5-4d6e-9d18-d34abf44af02"},{"content":"<p><math alttext=\"5\"><mn>5</mn>\n</math></p>","id":"f7707352-7a41-41a7-a120-8e8d6dc57e04"},{"content":"<p><math alttext=\"8\"><mn>8</mn>\n</math></p>","id":"b4573a81-e704-45ed-840f-8badfdd6e5e0"},{"content":"<p><math alttext=\"9\"><mn>9</mn>\n</math></p>","id":"f227815d-2851-4ac8-a99b-8768c426f2be"}],"externalid":"d900a2e7-10e1-484e-a11a-0c2fe3bbb04f","keys":["f7707352-7a41-41a7-a120-8e8d6dc57e04"],"rationale":"<p style=\"text-align: left;\">Choice B is correct. It's given that the graph models the number of active projects a company was working on <math alttext=\"x\"><mi>x</mi>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>. Therefore, the value of <math alttext=\"x\"><mi>x</mi>\n</math> that corresponds to the end of November <math alttext=\"2012\"><mn>2012</mn></math> is <math alttext=\"0\"><mn>0</mn>\n</math>. The point at which <math alttext=\"x equals 0\"><mrow>\n\t<mi>x</mi>\n\t<mo>=</mo>\n\t<mn>0</mn>\n</mrow>\n</math> is the <em>y</em>-intercept of the graph. It follows that the <em>y</em>-intercept of the graph shown is the point <math alttext=\"left parenthesis 0 comma 5 right parenthesis\"><mfenced><mrow><mn>0</mn><mo>,</mo><mn>5</mn></mrow></mfenced></math>. Therefore, according to the model, the predicted number of active projects the company was working on at the end of November <math alttext=\"2012\"><mn>2012</mn></math> is <math alttext=\"5\"><mn>5</mn>\n</math>.</p>\n<p style=\"text-align: left;\">Choice A is incorrect. This is the value of <math alttext=\"x\"><mi>x</mi>\n</math> that corresponds to the end of November <math alttext=\"2012\"><mn>2012</mn></math>, not the predicted number of active projects the company was working on at the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>\n<p style=\"text-align: left;\">Choice C is incorrect. This is the predicted number of active projects the company was working on <math alttext=\"2\"><mn>2</mn>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>\n<p style=\"text-align: left;\">Choice D is incorrect. This is the predicted number of active projects the company was working on <math alttext=\"4\"><mn>4</mn>\n</math> months after the end of November <math alttext=\"2012\"><mn>2012</mn></math>.</p>","stem":"<p style=\"text-align: center;\"><figure class='image'><svg height=\"275.22pt\" version=\"1.1\" viewBox=\"0 0 286.56 275.22\" width=\"286.56pt\" xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\" role=\"img\" aria-label=\"Graph of a parabola in the x y plane with the origin labeled O. The x axis ranges from 0 to 6. The y axis ranges from 0 to 13. Refer to long description.\">\n <defs>\n  <style type=\"text/css\">\n*{stroke-linecap:butt;stroke-linejoin:round;}\n  </style>\n </defs>\n <g